#!/usr/bin/env python3
# patch-158-E2: status pipeline, service deletion, inline edits, asset rename
"""
Brings the multi-asset view closer to legacy parity.

What ships:
  - Status pipeline card (matches legacy exactly) above customer card.
    Click any step to transition.
  - Terminal status card (cancelled / refunded) with Reopen button.
  - Inline edit of price + duration on every service/addon row.
    Blur to save. Select-all-on-focus for snappy editing.
  - Remove (X) button on every service/addon row — both pinned
    to assets AND loose ones.
  - Asset rename: click the asset name to edit. Saves on blur.
  - Subtotal refresh wired through everywhere: when items removed,
    when prices/durations changed, asset subtotal_cents updates and
    grand total recalculates.
  - New controller op: rename_appointment_asset (snapshot only).
  - Existing ops extended: remove_service, remove_addon, update_line_item
    now refresh the parent asset subtotal when applicable.

Still deferred to later patches:
  - E3: charges + payments (mark paid, partial payment, remove charge)
  - E4: inventory parts add/remove
  - E5: notes + work order responses
  - E6: activity timeline + special orders display

Standalone Python. Idempotent.
"""
